merge into customer_summary t using (select customer_id, sum(amount) amount from orders where created_at >= date '2026-04-01' group by customer_id) s on (t.customer_id = s.customer_id) when matched then update set t.amount = s.amount, t.updated_at = sysdate when not matched then insert (customer_id, amount, updated_at) values (s.customer_id, s.amount, sysdate);
